import type { Offer, Product } from "@/data/products";
import { materializeOfferEvidence } from "@/modules/commerce/offer-evidence";
import { isOfferFresh } from "@/modules/commerce/offer-freshness";

const checkedAt = "2026-08-14T17:00:00Z";

type ExactNgOptions = Pick<
  Offer,
  | "available"
  | "expiresAt"
  | "inventoryQuantity"
  | "sellerName"
  | "sellerScore"
  | "priceComparison"
> & {
  observedAt?: string;
  stock?: NonNullable<Offer["priceObservation"]>["stock"];
  verificationMethod?: "manual" | "retailer_page" | "api";
};

const exactNg = (
  retailer: string,
  url: string,
  trust: number,
  priceNgn: number,
  observedVariant: string,
  observedSize: string,
  options: Partial<ExactNgOptions> = {},
): Offer => {
  const observationTime = options.observedAt ?? checkedAt;
  const evidenceBasis =
    options.verificationMethod === "api" ? "retailer-api" : "retailer-page";
  return {
    retailer,
    url,
    trust,
    available: options.available ?? true,
    priceNgn,
    checkedAt: observationTime,
    expiresAt: options.expiresAt,
    match: "exact",
    inventoryQuantity: options.inventoryQuantity,
    sellerName: options.sellerName,
    sellerScore: options.sellerScore,
    priceComparison: options.priceComparison,
    listingEvidence: {
      observedAt: observationTime,
      sourceUrl: url,
      basis: evidenceBasis,
    },
    priceObservation: {
      observedAt: observationTime,
      variant: observedVariant,
      size: observedSize,
      stock:
        options.stock ??
        (options.available === false ? "out-of-stock" : "in-stock"),
      landedCost: "unknown",
    },
    location: ["NG"],
  };
};

